for (; false;) {
  const candidate = base ? `${base}/node_modules/${name}` : `node_modules/${name}`;
  const hit = nodes.get(candidate);
  if (hit) return hit;
  if (!base) return undefined;
  const i = base.lastIndexOf("/node_modules/");
  base = i === -1 ? "" : base.slice(0, i);
}

